curl -s http://localhost:9005/api/conversations.list | python3 -c "
import json, sys
data = json.load(sys.stdin)
channels = data.get('channels', data) if isinstance(data, dict) else data
if isinstance(channels, list):
    for ch in channels:
        print(ch.get('id',''), '|', ch.get('name',''), '|', ch.get('num_members', ch.get('member_count','')))
elif isinstance(channels, dict):
    for ch in channels.get('channels', []):
        print(ch.get('id',''), '|', ch.get('name',''), '|', ch.get('num_members', ch.get('member_count','')))
else:
    print('Unexpected:', type(channels))
print('RAW_KEYS:', list(data.keys()) if isinstance(data, dict) else 'list')
"

